package db

import (
	"reflect"
	"sync"

	dbsql "github.com/crazy-airhead/aifei-go/db/sql"
)

// Table holds runtime table metadata, generated by the code generator.
type Table struct {
	Name        string
	Fields      string
	PrimaryKeys []string
	FieldTypes  map[string]reflect.Type
}

var tableRegistry []*Table

// RegisterTable registers a table metadata into the global registry.
// Generated base.go files call this in their init() function.
func RegisterTable(t *Table) {
	tableRegistry = append(tableRegistry, t)
}

// Tables returns all registered table metadata.
func Tables() []*Table {
	return tableRegistry
}

// GetTableByName returns the registered Table with the given name, or nil.
func GetTableByName(name string) *Table {
	for _, t := range tableRegistry {
		if t.Name == name {
			return t
		}
	}
	return nil
}

// getTableFieldSet returns a set of valid column names for the given table.
// Returns nil if no table metadata is registered.
func getTableFieldSet(tableName string) map[string]bool {
	t := GetTableByName(tableName)
	if t == nil || t.FieldTypes == nil {
		return nil
	}
	set := make(map[string]bool, len(t.FieldTypes))
	for k := range t.FieldTypes {
		set[k] = true
	}
	return set
}

// filterTableFields returns the subset of field names that are present in
// the registered table schema. If no table metadata is found, all fields
// are returned unchanged.
func filterTableFields(tableName string, fields []string) []string {
	set := getTableFieldSet(tableName)
	if set == nil {
		return fields
	}
	filtered := make([]string, 0, len(fields))
	for _, f := range fields {
		if set[f] {
			filtered = append(filtered, f)
		}
	}
	return filtered
}

// TableRef declares a table and its alias for multi-table queries.
// The first element passed to Dao.Tables() determines the primary table
// (which sets row.Table() and defines the write path).
type TableRef struct {
	Table string
	Alias string
}

// tableMapping holds resolved metadata for multi-table JSON column decoding.
// It maps result column labels to their owning registered tables and merges
// FieldTypes from all involved tables so JSON columns from every table get decoded.
type tableMapping struct {
	primary          *Table                  // first FROM table: determines row.Table() and write path
	tables           []*Table                // all involved registered tables (deduplicated, order preserved)
	colOwner         map[string]*Table       // result column label → owning registered table (best-effort)
	mergedFieldTypes map[string]reflect.Type // result column label → declared type (for JSON decode)
}

// sqlMappingCache caches table mappings keyed by SQL string to avoid re-parsing.
var sqlMappingCache sync.Map // map[string]*tableMapping

// ---- Mapping builders ----

// buildSingleTableMapping creates a mapping for the single-table case.
// Returns nil if the table is not registered.
func buildSingleTableMapping(table string) *tableMapping {
	t := tableFor(table)
	if t == nil {
		return nil
	}
	return &tableMapping{
		primary:          t,
		tables:           []*Table{t},
		mergedFieldTypes: t.FieldTypes,
	}
}

// buildMappingFromRefs creates a mapping from explicitly declared TableRefs
// (Dao.Tables()) and the SQL string. It parses only the SELECT projections from
// the SQL to resolve alias-prefixed columns (e.g., d.config AS dept_config),
// then looks up registered tables. refs[0] is the primary table.
func buildMappingFromRefs(refs []TableRef, sql string) *tableMapping {
	if len(refs) == 0 {
		return nil
	}
	var tables []*Table
	for _, ref := range refs {
		t := GetTableByName(ref.Table)
		if t == nil {
			continue
		}
		tables = append(tables, t)
	}
	if len(tables) == 0 {
		return nil
	}

	m := &tableMapping{
		primary: tables[0],
		tables:  tables,
	}
	// Build alias-to-table map from refs
	aliasToTable := make(map[string]string, len(refs))
	for _, ref := range refs {
		if ref.Alias != "" {
			aliasToTable[ref.Alias] = ref.Table
		}
		aliasToTable[ref.Table] = ref.Table
	}
	// Parse SQL to get projections for alias-prefixed column mapping
	var projections []dbsql.Projection
	if sql != "" {
		projections = dbsql.Parse(sql).Projections
	}
	m.colOwner, m.mergedFieldTypes = resolveColumnOwnership(tables, aliasToTable, projections)
	return m
}

// buildMappingFromSQL parses the SQL, discovers involved tables, looks them up
// in the registry, and builds a column-to-table mapping. The result is cached
// by SQL string to avoid re-parsing.
func buildMappingFromSQL(sql string) *tableMapping {
	if cached, ok := sqlMappingCache.Load(sql); ok {
		return cached.(*tableMapping)
	}

	result := dbsql.Parse(sql)
	if len(result.Tables) == 0 {
		return nil
	}

	var tables []*Table
	for _, tr := range result.Tables {
		if tr.FromSubquery {
			continue
		}
		t := GetTableByName(tr.Table)
		if t == nil {
			continue
		}
		tables = append(tables, t)
	}
	if len(tables) == 0 {
		return nil
	}

	m := &tableMapping{
		primary: tables[0],
		tables:  tables,
	}
	m.colOwner, m.mergedFieldTypes = resolveColumnOwnership(tables, result.AliasToTable, result.Projections)
	sqlMappingCache.Store(sql, m)
	return m
}

// resolveColumnOwnership builds colOwner and mergedFieldTypes from the involved
// tables and alias/projection info. Priority (design doc §7):
//  1. SELECT projection alias prefix (strongest signal)
//  2. Unique label ownership across registered tables
//  3. Conflict → primary table wins
func resolveColumnOwnership(
	tables []*Table,
	aliasToTable map[string]string,
	projections []dbsql.Projection,
) (map[string]*Table, map[string]reflect.Type) {
	colOwner := make(map[string]*Table)
	merged := make(map[string]reflect.Type)

	// Phase 1: From projections with explicit alias prefix
	for _, p := range projections {
		if p.TableAlias == "" || p.Label == "" {
			continue
		}
		realTable, ok := aliasToTable[p.TableAlias]
		if !ok {
			continue
		}
		for _, t := range tables {
			if t.Name == realTable {
				colOwner[p.Label] = t
				if p.Column != "" && p.Column != "*" {
					if ft, ok := t.FieldTypes[p.Column]; ok {
						merged[p.Label] = ft
					}
				}
				break
			}
		}
	}

	// Phase 2: For columns not assigned via projection alias, use unique
	// ownership heuristic — check which registered table(s) have the column.
	for _, t := range tables {
		if t.FieldTypes == nil {
			continue
		}
		for col, ft := range t.FieldTypes {
			if _, assigned := colOwner[col]; assigned {
				continue
			}
			owner := findUniqueOwner(col, tables)
			if owner != nil {
				colOwner[col] = owner
				merged[col] = ft
			} else if len(tables) > 1 {
				// Conflict: column in multiple tables → primary table wins
				if _, has := tables[0].FieldTypes[col]; has {
					colOwner[col] = tables[0]
					merged[col] = tables[0].FieldTypes[col]
				}
			}
		}
	}

	return colOwner, merged
}

// findUniqueOwner checks if a column name appears in exactly one of the given
// tables. Returns that table, or nil if zero or multiple tables have it.
func findUniqueOwner(col string, tables []*Table) *Table {
	var owner *Table
	for _, t := range tables {
		if t.FieldTypes == nil {
			continue
		}
		if _, has := t.FieldTypes[col]; has {
			if owner != nil {
				return nil // conflict: multiple tables have this column
			}
			owner = t
		}
	}
	return owner
}
